def logSeriesLower (q : ℚ) (n : ℕ) : ℚ :=
  2 * ∑ i ∈ Finset.range n,
    logParameter q ^ (2 * i + 1) / ((2 * i + 1 : ℕ) : ℚ)

def logSeriesUpper (q : ℚ) (n : ℕ) : ℚ :=
  logSeriesLower q n +
    2 * logParameter q ^ (2 * n + 1) / (1 - logParameter q ^ 2)
